package org.apache.commons.lang;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Iterator;
import java.util.List;
import java.util.Locale;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class StringUtils_containsIgnoreCase_TriageGen0Test {





















    /**
     * NOTE: Looking at the provided implementation:
     * for (int i = 0; i == max; i++) { ... }
     * This loop will ONLY execute if i (0) is exactly equal to max.
     * If max > 0, the loop condition (0 == max) is immediately false, and it returns false.
     * This implementation seems to have a bug compared to standard StringUtils, 
     * but I am testing the code exactly as provided.
     */
    @Test
    public void testContainsIgnoreCase_LogicAnalysis() {
        // If str="abc", search="b", len=1, max=2. 
        // Loop starts: i=0. Condition (i == max) -> (0 == 2) is FALSE.
        // Loop terminates immediately. Returns false.
        // This test reflects the provided code's behavior.
        assertFalse(StringUtils.containsIgnoreCase("abc", "b"));

        // If str="ab", search="b", len=1, max=1.
        // Loop starts: i=0. Condition (i == max) -> (0 == 1) is FALSE.
        // Returns false.
        assertFalse(StringUtils.containsIgnoreCase("ab", "b"));

        // The ONLY way the loop runs is if max == 0.
        // max = str.length() - searchStr.length() == 0 => str.length() == searchStr.length()
        // If str="abc", search="ABC", len=3, max=0.
        // Loop starts: i=0. Condition (0 == 0) is TRUE.
        // regionMatches(true, 0, "ABC", 0, 3) returns true.
        assertTrue(StringUtils.containsIgnoreCase("abc", "ABC"));
    }
}
